def seed_fields_if_empty(conn: sqlite3.Connection) -> int:
    """Insert the Maur/Aligarh sample plots if `fields` is empty.

    Returns the number of rows inserted (0 on re-runs).
    """
    if get_all_fields(conn):
        return 0
    count = 0
    for plot_id, owner, village, _district, wkt in SAMPLE_PLOTS:
        polygon = wkt_loads(wkt)
        coords = list(polygon.exterior.coords)
        name = f"{owner} ({village})"
        field = build_field_polygon(name, coords, field_id=f"plot_{plot_id}")
        upsert_field(conn, field)
        count += 1
    return count
